// Safe PUBLIC starter mission. Edit these prompts in your private n8n instance.
// Each role drafts an output; no customer accounts or external side effects.
const mission = "Prepare an evidence-based, non-confidential operating plan for a one-person technology company.";
const roles = [
  ["research","Identify three verifiable public sources and remaining unknowns"],
  ["engineering","Draft a public software-maintenance backlog; propose no direct repository writes"],
  ["browser","Design a read-only public-site research checklist; do not log in"],
  ["creative","Propose three visual directions without publishing assets"],
  ["marketing","Draft a neutral launch announcement for founder review"],
  ["operations","Draft an internal weekly operating checklist"],
  ["simulation","Identify bounded numerical checks that might test a product claim"],
  ["support","Draft customer-support FAQs; do not message customers"],
  ["verification","Critique unsupported claims and assign evidence requirements"]
];
return roles.map(([role,instruction]) => ({json:{role,mission,instruction,run_scope:"draft_only",authorization:"none",owner_review_required:true}}));

// Model-generated work is UNVERIFIED until its sources and assertions are checked.
// This workflow has no webhooks, credentials, or write-capable business connectors.
return $input.all().map((item, index) => ({
  json: {
    item_index: index,
    status: "DRAFT_AWAITING_FOUNDER_REVIEW",
    draft_untrusted: String(item.json.output || "").slice(0,12000),
    independent_verification_performed: false,
    external_actions_executed: false,
    owner_approval_required: true
  }
}));
